    if regiao not in ("S", "SE", "CO", "NE", "N"):
        raise ValueError("região inválida")
    if valor_pedido < 0:
        raise ValueError("valor_pedido deve ser >= 0")

    # Usar Decimal para precisão em cálculos monetários
    peso = Decimal(str(peso_kg))
    valor = Decimal(str(valor_pedido))

    # 2. Tarifa base por peso
    if peso <= 1:
        base = Decimal("12.00")
    elif peso <= 5:
        fracoes = int(math.ceil(peso_kg - 1))
        base = Decimal("12.00") + Decimal("3.50") * fracoes
    else:
        fracoes = int(math.ceil(peso_kg - 5))
        base = Decimal("26.00") + Decimal("2.80") * fracoes

    # 3. Multiplicador regional
    mult_map = {"S": Decimal("1.00"), "SE": Decimal("1.00"), "CO": Decimal("1.20"), "NE": Decimal("1.35"), "N": Decimal("1.50")}
